#include <iostream>

int main() {
    double radius = 0.0;
    if (std::cin >> radius) {
        constexpr double pi = 3.141592653589793;
        if (radius >= 0.0) {
            double area = radius * radius * pi;
            std::cout << "Area: " << area << "\n";
        } else {
            std::cout << "Negative radius\n";
        }
    }
    return 0;
}

