    std::cout << number << " is even.\n";
std::cout << number << " is odd.\n";
```

example.code:
#include <iostream>

int main() {
    double score = 0.0;
    if (std::cin >> score) {
        char grade = 'F';
        if (score >= 90.0) {
            grade = 'A';
        } else if (score >= 80.0) {
            grade = 'B';
        } else if (score >= 70.0) {
            grade = 'C';
        } else if (score >= 60.0) {
            grade = 'D';
        } else {
            grade = 'F';
        }
        std::cout << "Grade is " << grade << "\n";
    }
    return 0;
}
